"""CLI interface with proper dependency wiring."""

from __future__ import annotations

import argparse
import subprocess
import sys
from pathlib import Path
from typing import TYPE_CHECKING

from flashcards_generator.adapters.anki_connect_adapter import (
    DEFAULT_ANKI_CONNECT_URL,
    AnkiConnectAdapter,
)
from flashcards_generator.adapters.notebooklm_adapter import NotebookLMAdapter
from flashcards_generator.application.csv_merger import CsvMerger
from flashcards_generator.application.dto.generate_request import (
    GenerateFlashcardsRequest,
)
from flashcards_generator.application.dto.merge_request import MergeCsvRequest
from flashcards_generator.application.use_cases import (
    GenerateFlashcardsUseCase,
)
from flashcards_generator.domain.exceptions import (
    AnkiConnectError,
    CSVMergeError,
)
from flashcards_generator.domain.ports.anki_exporter import AnkiExporterPort
from flashcards_generator.infrastructure.chunk_state_repository import (
    FileSystemChunkStateRepository,
)
from flashcards_generator.infrastructure.logging_config import (
    configure_logging,
    get_logger,
)
from flashcards_generator.infrastructure.paths import find_notebooklm

if TYPE_CHECKING:
    from flashcards_generator.domain.entities import Deck

logger = get_logger("cli")


def _positive_int(value: str) -> int:
    """Parse a positive integer for destructive cleanup selection."""
    parsed = int(value)
    if parsed <= 0:
        raise argparse.ArgumentTypeError("deve ser um inteiro positivo")
    return parsed


class CLI:
    """Command-line interface for flashcards generator."""

    def __init__(self) -> None:
        """Initialize CLI with argument parser."""
        self.parser = self._create_parser()

    def _create_parser(self) -> argparse.ArgumentParser:
        """Create argument parser with subcommands."""
        parser = argparse.ArgumentParser(
            description="Gera flashcards com Cloze Deletion a partir de PDFs"
        )
        parser.add_argument(
            "--log-level",
            choices=["DEBUG", "INFO", "WARNING", "ERROR"],
            default="INFO",
            help="Nível de log (padrão: INFO)",
        )

        subparsers = parser.add_subparsers(
            dest="command", help="Comandos disponíveis"
        )

        # Generate command (default)
        generate_parser = subparsers.add_parser(
            "generate", help="Gerar flashcards de PDFs"
        )
        generate_parser.add_argument(
            "--input-dir",
            "-i",
            required=True,
            type=Path,
            help="Diretório com pastas de temas contendo PDFs",
        )
        generate_parser.add_argument(
            "--output-dir",
            "-o",
            type=Path,
            default=Path("./output"),
            help=(
                "Diretório raiz de saída; a estrutura relativa do input "
                "é preservada dentro dele"
            ),
        )
        generate_parser.add_argument(
            "--difficulty",
            "-d",
            choices=["easy", "medium", "hard"],
            default="medium",
        )
        generate_parser.add_argument(
            "--quantity",
            "-q",
            choices=["fewer", "standard", "more"],
            default="standard",
        )
        generate_parser.add_argument(
            "--instructions", help="Instruções customizadas"
        )
        generate_parser.add_argument(
            "--language",
            "-l",
            default="pt_BR",
            help="Idioma dos flashcards (padrão: pt_BR)",
        )
        generate_parser.add_argument(
            "--no-wait",
            action="store_true",
            help="Não aguarda conclusão",
        )
        generate_parser.add_argument("--timeout", type=int, default=900)
        generate_parser.add_argument("--skip-auth-check", action="store_true")
        generate_parser.add_argument(
            "--include",
            type=str,
            help="Padrão glob para incluir PDFs (ex: 'capitulo*.pdf')",
        )
        generate_parser.add_argument(
            "--exclude",
            type=str,
            help="Padrão glob para excluir PDFs (ex: '*_old.pdf')",
        )
        generate_parser.add_argument(
            "--files",
            type=str,
            help="Lista explícita de PDFs separados por vírgula",
        )
        generate_parser.add_argument(
            "--anki-deck",
            type=str,
            help=(
                "Importar cards diretamente no deck Anki informado "
                "(opcional; suporta `::` para decks hierárquicos)"
            ),
        )
        generate_parser.add_argument(
            "--anki-connect-url",
            type=str,
            help=(
                "URL local do AnkiConnect (padrão: "
                f"{DEFAULT_ANKI_CONNECT_URL})"
            ),
        )
        generate_parser.add_argument(
            "--anki-api-key",
            type=str,
            help="Chave opcional configurada no AnkiConnect",
        )
        # Cleanup command
        cleanup_parser = subparsers.add_parser(
            "cleanup", help="Limpar notebooks do NotebookLM"
        )
        cleanup_selector = cleanup_parser.add_mutually_exclusive_group(
            required=True
        )
        cleanup_selector.add_argument(
            "--days",
            "-d",
            type=_positive_int,
            help=(
                "Deletar apenas notebooks criados nos últimos N dias "
                "(ex: 1=hoje, 2=ontem+hoje)"
            ),
        )
        cleanup_selector.add_argument(
            "--all",
            "-a",
            action="store_true",
            help="Deletar todos os notebooks",
        )
        cleanup_parser.add_argument("--skip-auth-check", action="store_true")

        merge_parser = subparsers.add_parser(
            "merge", help="Mesclar arquivos CSV de flashcards"
        )
        merge_parser.add_argument(
            "--folder",
            "-f",
            required=True,
            type=Path,
            help="Pasta contendo arquivos CSV para mesclar",
        )
        merge_parser.add_argument(
            "--output",
            "-o",
            type=str,
            default="merged_flashcards.csv",
            help="Nome do arquivo de saída (padrão: merged_flashcards.csv)",
        )
        merge_parser.add_argument(
            "--deduplicate",
            "-d",
            action="store_true",
            help="Remover flashcards duplicados durante a mescla",
        )
        merge_parser.add_argument(
            "--no-recursive",
            action="store_true",
            help="Não buscar em subpastas (padrão: busca recursiva)",
        )

        return parser

    def check_auth(self) -> bool:
        """Check if user is authenticated with NotebookLM."""
        notebooklm = find_notebooklm()
        try:
            result = subprocess.run(
                [notebooklm, "auth", "check"],
                capture_output=True,
                text=True,
                check=False,
                timeout=10,
            )
            return result.returncode == 0
        except subprocess.TimeoutExpired:
            logger.error("Tempo esgotado ao verificar autenticação")
        except FileNotFoundError:
            logger.error("Executável notebooklm não encontrado")
        except OSError as error:
            logger.error(f"Não foi possível verificar autenticação: {error}")
        return False

    def _validate_input(self, input_dir: Path) -> bool:
        """Validate input directory exists and is a directory."""
        if not input_dir.exists():
            logger.error(f"Diretório não existe: {input_dir}")
            return False
        if not input_dir.is_dir():
            logger.error(f"Diretório inválido: {input_dir}")
            return False
        return True

    def _authenticate(self, skip_auth_check: bool) -> bool:
        """Verify authentication."""
        if skip_auth_check:
            return True
        logger.info("Verificando autenticação...")
        if not self.check_auth():
            logger.error("Não autenticado. Execute: notebooklm login")
            return False
        logger.info("Autenticado")
        return True

    def _set_language(self, language: str) -> None:
        """Set language for NotebookLM."""
        notebooklm = find_notebooklm()
        try:
            result = subprocess.run(
                [notebooklm, "language", "set", language],
                capture_output=True,
                text=True,
                check=False,
                timeout=10,
            )
        except subprocess.TimeoutExpired:
            logger.warning(
                "Não foi possível configurar o idioma: tempo esgotado"
            )
            return
        except FileNotFoundError:
            logger.warning(
                "Não foi possível configurar o idioma: executável não encontrado"
            )
            return
        except OSError as error:
            logger.warning(f"Não foi possível configurar o idioma: {error}")
            return

        if result.returncode == 0:
            logger.info(f"Idioma configurado: {language}")
            return

        reason = result.stderr.strip()[:200] or (
            f"código de saída {result.returncode}"
        )
        logger.warning(f"Não foi possível configurar o idioma: {reason}")

    def _create_adapter(self, timeout: int = 900) -> NotebookLMAdapter:
        """Create NotebookLM adapter."""
        notebooklm_path = find_notebooklm()
        return NotebookLMAdapter(notebooklm_path, timeout=timeout)

    def _create_use_case(
        self, args: argparse.Namespace
    ) -> GenerateFlashcardsUseCase:
        """Create use case with dependencies wired."""
        generator = self._create_adapter(args.timeout)
        return GenerateFlashcardsUseCase(
            generator=generator,
            chunk_state_repository=FileSystemChunkStateRepository(),
        )

    @staticmethod
    def _create_anki_exporter(
        args: argparse.Namespace,
    ) -> AnkiExporterPort | None:
        """Create the opt-in AnkiConnect exporter."""
        if (
            args.anki_deck is None
            and args.anki_connect_url is None
            and args.anki_api_key is None
        ):
            return None
        if args.anki_deck is None:
            raise ValueError(
                "--anki-deck é obrigatório ao configurar o AnkiConnect"
            )
        return AnkiConnectAdapter(
            deck_name=args.anki_deck,
            url=args.anki_connect_url or DEFAULT_ANKI_CONNECT_URL,
            api_key=args.anki_api_key,
        )

    @staticmethod
    def _export_to_anki(
        decks: list[Deck],
        exporter: AnkiExporterPort,
    ) -> int:
        """Export generated decks and return the imported card count."""
        imported = sum(exporter.export(deck) for deck in decks)
        logger.info(f"✅ {imported} card(s) importado(s) no Anki")
        return imported

    def _create_request(
        self, args: argparse.Namespace
    ) -> GenerateFlashcardsRequest:
        """Create request DTO from CLI args."""
        explicit_files = []
        if args.files:
            explicit_files = [f.strip() for f in args.files.split(",")]
        return GenerateFlashcardsRequest(
            input_dir=args.input_dir,
            output_dir=args.output_dir,
            difficulty=args.difficulty,
            quantity=args.quantity,
            instructions=args.instructions or "",
            wait_for_completion=not args.no_wait,
            timeout=args.timeout,
            include_pattern=args.include,
            exclude_pattern=args.exclude,
            explicit_files=explicit_files,
        )

    def _log_config(self, request: GenerateFlashcardsRequest) -> None:
        """Log configuration."""
        logger.info("Iniciando...")
        logger.info(f"Entrada: {request.input_dir}")
        logger.info(
            f"Saída: {request.output_dir} (preservando a estrutura relativa)"
        )
        logger.info(f"Dificuldade: {request.difficulty}")
        logger.info(f"Quantidade: {request.quantity}")

    def _print_summary(self, decks: list[Deck]) -> None:
        """Print execution summary."""
        total_cards = sum(d.total_cards for d in decks)
        logger.info("=" * 60)
        logger.info("RESUMO")
        logger.info("=" * 60)
        logger.info(f"Temas: {len(decks)}")
        logger.info(f"Total de cards: {total_cards}")
        logger.info("Decks:")
        for deck in decks:
            status = "✅" if deck.flashcards else "⏳"
            logger.info(f"  {status} {deck.name}: {deck.total_cards} cards")

    def _run_generate(self, args: argparse.Namespace) -> int:
        """Run generate command."""
        if not self._validate_input(args.input_dir):
            return 1

        if not self._authenticate(args.skip_auth_check):
            return 1

        self._set_language(args.language)

        try:
            anki_exporter = self._create_anki_exporter(args)
        except ValueError as error:
            logger.error(f"Opções do AnkiConnect inválidas: {error}")
            return 1

        use_case = self._create_use_case(args)
        request = self._create_request(args)
        self._log_config(request)

        try:
            decks = use_case.execute(request)
        except KeyboardInterrupt:
            logger.info("\n⚠️  Operation cancelled by user")
            return 130

        if anki_exporter is not None:
            try:
                self._export_to_anki(decks, anki_exporter)
            except AnkiConnectError as error:
                logger.error(f"Falha na importação via AnkiConnect: {error}")
                return 1

        self._print_summary(decks)
        return 1 if use_case.last_run_had_errors is True else 0

    def _run_cleanup(self, args: argparse.Namespace) -> int:
        """Run cleanup command."""
        if not self._authenticate(args.skip_auth_check):
            return 1

        try:
            adapter = self._create_adapter()
            deleted, failed = self._delete_selected_notebooks(adapter, args)
        except OSError as error:
            logger.error(f"Não foi possível limpar notebooks: {error}")
            return 1

        if failed > 0:
            logger.warning(f"{failed} notebook(s) não puderam ser deletados")
            return 0 if deleted > 0 else 1

        logger.info(f"✅ {deleted} notebook(s) deletado(s) com sucesso")
        return 0

    @staticmethod
    def _delete_selected_notebooks(
        adapter: NotebookLMAdapter, args: argparse.Namespace
    ) -> tuple[int, int]:
        if args.days:
            logger.info(
                f"Deletando notebooks dos últimos {args.days} dia(s)..."
            )
            return adapter.delete_all_notebooks(
                days=args.days, show_progress=True
            )
        logger.info("Deletando todos os notebooks...")
        return adapter.delete_all_notebooks(show_progress=True)

    def _run_merge(self, args: argparse.Namespace) -> int:
        """Run merge command."""
        if not args.folder.exists() or not args.folder.is_dir():
            logger.error(f"Pasta inválida ou inexistente: {args.folder}")
            return 1

        try:
            request = MergeCsvRequest(
                folder_path=args.folder,
                output_filename=args.output,
                deduplicate=args.deduplicate,
                recursive=not args.no_recursive,
            )
        except ValueError as error:
            logger.error(f"Opções de merge inválidas: {error}")
            return 1

        try:
            rows = CsvMerger.merge(request)
            output_path = args.folder / args.output
            logger.info(f"✅ {rows} flashcards mesclados em: {output_path}")
            return 0
        except CSVMergeError as e:
            logger.error(f"Erro ao mesclar: {e.reason}")
            return 1

    def run(self) -> int:
        """Run CLI."""
        args = self.parser.parse_args()
        configure_logging(args.log_level)

        if args.command == "cleanup":
            return self._run_cleanup(args)
        elif args.command == "merge":
            return self._run_merge(args)
        elif args.command == "generate":
            return self._run_generate(args)
        self.parser.print_help()
        return 1


def main() -> None:
    """Entry point."""
    cli = CLI()
    try:
        sys.exit(cli.run())
    except KeyboardInterrupt:
        logger.info("\n⚠️  Operation cancelled by user")
        sys.exit(130)

"""CSV merger for combining flashcard files."""

from __future__ import annotations

import csv
import os
import tempfile
from collections.abc import Iterator
from pathlib import Path
from typing import TYPE_CHECKING

from flashcards_generator.domain.exceptions import CSVMergeError

if TYPE_CHECKING:
    from flashcards_generator.application.dto.merge_request import (
        MergeCsvRequest,
    )


class CsvMerger:
    """Merge multiple CSV flashcard files into one."""

    @staticmethod
    def merge(request: MergeCsvRequest) -> int:
        """Merge all CSV files in folder_path into single output file.

        Args:
            request: MergeCsvRequest with folder, output name, dedup flag

        Returns:
            Number of rows written to merged file

        Raises:
            CSVMergeError: If folder doesn't exist or merge fails
        """
        output_path = request.folder_path / request.output_filename
        try:
            csv_files = CsvMerger._source_files(request, output_path)
            return CsvMerger._write_rows(
                output_path, csv_files, deduplicate=request.deduplicate
            )

        except CSVMergeError:
            raise
        # This application boundary must translate every merge failure consistently.
        except Exception as e:
            raise CSVMergeError(request.folder_path, str(e)) from e

    @staticmethod
    def _source_files(
        request: MergeCsvRequest, output_path: Path
    ) -> list[Path]:
        if not request.folder_path.exists():
            raise CSVMergeError(request.folder_path, "Folder does not exist")
        pattern = "**/*.csv" if request.recursive else "*.csv"
        csv_files = [
            path
            for path in sorted(request.folder_path.glob(pattern))
            if path != output_path
        ]
        if not csv_files:
            raise CSVMergeError(
                request.folder_path, "No CSV files found in folder"
            )
        return csv_files

    @staticmethod
    def _write_rows(
        output_path: Path,
        csv_files: list[Path],
        *,
        deduplicate: bool,
    ) -> int:
        temporary_path: Path | None = None
        try:
            with tempfile.NamedTemporaryFile(
                mode="w",
                newline="",
                encoding="utf-8",
                dir=output_path.parent,
                prefix=f".{output_path.name}.",
                suffix=".tmp",
                delete=False,
            ) as out_f:
                temporary_path = Path(out_f.name)
                writer = csv.writer(out_f, quoting=csv.QUOTE_ALL)
                rows = CsvMerger._iter_rows(csv_files)
                if deduplicate:
                    rows = CsvMerger._deduplicated(rows)
                total_rows = 0
                for front, back in rows:
                    writer.writerow([front, back])
                    total_rows += 1
                out_f.flush()
                os.fsync(out_f.fileno())

            temporary_path.replace(output_path)
            return total_rows
        except Exception:
            if temporary_path is not None:
                temporary_path.unlink(missing_ok=True)
            raise

    @staticmethod
    def _iter_rows(csv_files: list[Path]) -> Iterator[tuple[str, str]]:
        for csv_file in csv_files:
            with open(csv_file, newline="", encoding="utf-8") as in_f:
                for row_number, row in enumerate(csv.reader(in_f), start=1):
                    if len(row) < 2:
                        continue
                    if len(row) != 2:
                        raise CSVMergeError(
                            csv_file,
                            f"Row {row_number} must contain exactly 2 columns; "
                            f"found {len(row)} columns",
                        )
                    yield row[0], row[1]

    @staticmethod
    def _deduplicated(
        rows: Iterator[tuple[str, str]],
    ) -> Iterator[tuple[str, str]]:
        seen: set[tuple[str, str]] = set()
        for row in rows:
            key = (row[0].strip(), row[1].strip())
            if key not in seen:
                seen.add(key)
                yield row

    json_path = task.pdf_output_path / _safe_filename(
        f"chunk{task.chunk_index}", "_raw.json"
    )
    try:
        self.generator.download_flashcards(
            notebook_id, artifact_id, json_path
        )
        flashcards = self.generator.parse_flashcards(json_path)
    finally:
        self._cleanup_raw_file(json_path)

    cloze_cards = self._convert_flashcards(flashcards, task.deck_name)
    return Deck(
        name=f"{task.deck_name}_chunk{task.chunk_index}",
        description=(f"Chunk {task.chunk_index} of {task.total_chunks}"),
        flashcards=cloze_cards,
        notebook_id=notebook_id,
    )

def _cleanup_chunk_notebook(
    self,
    notebook_id: str | None,
    chunk_index: int,
    total_chunks: int,
) -> None:
    """Delete a completed chunk notebook when it is still tracked."""
    if not notebook_id or notebook_id not in self._created_notebooks:
        return
    try:
        self.generator.delete_notebook(notebook_id)
        self._created_notebooks.remove(notebook_id)
        logger.debug(
            f"Chunk {chunk_index}/{total_chunks}: notebook cleaned up"
        )
    except NotebookCleanupError as error:
        logger.warning(f"Failed to cleanup chunk notebook: {error}")

def _process_pdf(
    self,
    pdf_path: Path,
    input_path: Path,
    output_path: Path,
    request: GenerateFlashcardsRequest,
    source_path: Path | None = None,
) -> Deck | None:
    """Process single PDF file."""
    deck_name = self._get_deck_name(pdf_path, input_path)
    pdf_output_path = self._get_output_subdir(
        pdf_path, input_path, output_path
    )
    if self._output_deck_exists(pdf_output_path, pdf_path.stem):
        logger.info(f"Skipping {pdf_path.name} - CSV already exists")
        return None

    self._log_pdf_header(pdf_path, input_path, deck_name)
    try:
        return self._process_pdf_content(
            pdf_path,
            deck_name,
            pdf_output_path,
            request,
            source_path or pdf_path,
        )
    except GenerationError as e:
        self._last_pdf_had_error = True
        logger.error(f"Generation error: {e}")
        return None
    except (OSError, ValueError, RuntimeError) as e:
        self._last_pdf_had_error = True
        logger.error(f"Processing error: {e}")
        return None
    except (AttributeError, KeyError, TypeError) as e:
        # Catch malformed responses and unexpected object shapes gracefully.
        self._last_pdf_had_error = True
        logger.error(f"Unexpected error processing PDF: {e}")
        return None

@staticmethod
def _output_deck_exists(pdf_output_path: Path, pdf_stem: str) -> bool:
    """Return whether the expected final CSV already exists."""
    return (pdf_output_path / _safe_filename(pdf_stem, ".csv")).exists()

@staticmethod
def _log_pdf_header(
    pdf_path: Path, input_path: Path, deck_name: str
) -> None:
    """Log the source currently being processed."""
    logger.info("=" * BORDER_LENGTH)
    logger.info(f"PDF: {pdf_path.relative_to(input_path)}")
    logger.info(f"Deck: {deck_name}")
    logger.info("=" * BORDER_LENGTH)

def _process_pdf_content(
    self,
    pdf_path: Path,
    deck_name: str,
    pdf_output_path: Path,
    request: GenerateFlashcardsRequest,
    processing_path: Path,
) -> Deck | None:
    """Choose chunked or regular processing for one PDF."""
    if self._should_chunk_pdf(pdf_path, processing_path):
        logger.info(
            f"Large PDF detected (>{PDF_CHUNKING_THRESHOLD} pages), "
            "using chunking..."
        )
        deck = self._process_large_pdf(
            pdf_path,
            deck_name,
            pdf_output_path,
            request,
            processing_path,
        )
    else:
        deck = self._process_regular_pdf(
            pdf_path,
            deck_name,
            pdf_output_path,
            request,
            processing_path,
        )
    if deck is None:
        self._last_pdf_had_error = True
    return deck

def _should_chunk_pdf(self, pdf_path: Path, processing_path: Path) -> bool:
    """Return whether the source is a PDF above the chunking threshold."""
    return (
        pdf_path.suffix.lower() == ".pdf"
        and self.pdf_chunker.needs_chunking(
            processing_path, threshold=PDF_CHUNKING_THRESHOLD
        )
    )

def _process_regular_pdf(
    self,
    pdf_path: Path,
    deck_name: str,
    pdf_output_path: Path,
    request: GenerateFlashcardsRequest,
    processing_path: Path,
) -> Deck | None:
    """Generate cards for a source that does not need chunking."""
    notebook_id = self._create_notebook(deck_name)
    source_id = self._add_pdf_source(notebook_id, processing_path)
    if not source_id:
        self._last_pdf_had_error = True
        return None
    logger.info("Processing source...")
    self.generator.wait_for_source(
        notebook_id, source_id, timeout=SOURCE_WAIT_TIMEOUT
    )
    deck = self._generate_flashcards(
        notebook_id, deck_name, pdf_output_path, request, pdf_path.stem
    )
    if deck is None:
        self._last_pdf_had_error = True
    return deck

def _generate_flashcards(
    self,
    notebook_id: str,
    deck_name: str,
    pdf_output_path: Path,
    request: GenerateFlashcardsRequest,
    pdf_stem: str = "",
) -> Deck | None:
    """Generate flashcards for notebook."""
    instructions = request.instructions or self.DEFAULT_INSTRUCTIONS
    gen_config = GenerationConfig(
        difficulty=request.difficulty,
        quantity=request.quantity,
        instructions=instructions,
        timeout_seconds=request.timeout,
        wait_for_completion=request.wait_for_completion,
    )

    logger.info("Generating flashcards...")
    artifact_id = self.generator.generate_flashcards(
        notebook_id, gen_config
    )

    if not artifact_id:
        logger.error("Failed to generate flashcards")
        return None

    return self._handle_artifact_completion(
        notebook_id,
        artifact_id,
        pdf_output_path,
        deck_name,
        request,
        pdf_stem,
    )

def _handle_artifact_completion(
    self,
    notebook_id: str,
    artifact_id: str,
    output_path: Path,
    deck_name: str,
    request: GenerateFlashcardsRequest,
    pdf_stem: str = "",
) -> Deck:
    """Handle artifact completion or wait."""
    logger.info("Waiting for generation...")

    if not request.wait_for_completion:
        logger.info(f"Background generation. ID: {artifact_id}")
        return Deck(
            name=deck_name,
            description=f"Deck {deck_name} (generating)",
            notebook_id=notebook_id,
        )

    completed = self.generator.wait_for_artifact(
        notebook_id, artifact_id, timeout=request.timeout
    )

    if completed:
        return self._download_and_convert(
            notebook_id, artifact_id, output_path, deck_name, pdf_stem
        )

    logger.warning(f"Timeout. ID: {artifact_id}")
    logger.info(f"Notebook preserved for retry: {notebook_id}")
    return Deck(
        name=deck_name,
        description=f"Deck {deck_name}",
        notebook_id=notebook_id,
    )

def _download_and_convert(
    self,
    notebook_id: str,
    artifact_id: str,
    output_path: Path,
    deck_name: str,
    pdf_stem: str = "",
) -> Deck:
    """Download and convert flashcards."""
    # Use pdf_stem for temp file to avoid path duplication with deck_name
    temp_name = pdf_stem if pdf_stem else deck_name
    json_path = output_path / _safe_filename(temp_name, "_raw.json")
    flashcards = self._download_flashcards(
        notebook_id, artifact_id, json_path
    )
    deck = self._build_deck(notebook_id, deck_name, flashcards)
    self._delete_completed_notebook(notebook_id)
    return deck

def _download_flashcards(
    self, notebook_id: str, artifact_id: str, json_path: Path
) -> list[Flashcard]:
    """Download and parse cards, always removing the raw artifact."""
    try:
        self.generator.download_flashcards(
            notebook_id, artifact_id, json_path
        )
        return self.generator.parse_flashcards(json_path)
    finally:
        self._cleanup_raw_file(json_path)

@staticmethod
def _cleanup_raw_file(json_path: Path) -> None:
    """Remove one temporary raw JSON file."""
    try:
        json_path.unlink(missing_ok=True)
    except OSError as error:
        logger.warning(f"Failed to cleanup temp file: {error}")

def _convert_flashcards(
    self, flashcards: list[Flashcard], deck_name: str
) -> list[Flashcard]:
    """Convert source cards to cloze cards and attach the deck tag."""
    cloze_cards: list[Flashcard] = []
    tag = deck_name.lower().replace(" ", "_")
    for card in flashcards:
        cloze_card = self.converter.convert(card)
        if cloze_card:
            cloze_card.tags.append(tag)
            cloze_cards.append(cloze_card)
    return cloze_cards

def _build_deck(
    self,
    notebook_id: str,
    deck_name: str,
    flashcards: list[Flashcard],
) -> Deck:
    """Build and deduplicate a generated deck."""
    deck = Deck(
        name=deck_name,
        description=f"Deck de {deck_name}",
        flashcards=self._convert_flashcards(flashcards, deck_name),
        notebook_id=notebook_id,
    )
    removed = deck.deduplicate(similarity_threshold=0.85)
    if removed > 0:
        logger.info(f"Removed {removed} duplicate flashcards")
    return deck

def _delete_completed_notebook(self, notebook_id: str) -> None:
    """Delete a notebook after its artifact was downloaded."""
    try:
        self.generator.delete_notebook(notebook_id)
        if notebook_id in self._created_notebooks:
            self._created_notebooks.remove(notebook_id)
        logger.info("Notebook deleted")
    except NotebookCleanupError:
        pass

def _save_deck(self, deck: Deck, output_path: Path, pdf_stem: str) -> None:
    """Save deck to output directory."""
    csv_path = output_path / _safe_filename(pdf_stem, ".csv")
    self.exporter.export_csv(deck, csv_path)
    logger.info(f"Saved to: {csv_path}")

"""NotebookLM adapter implementing FlashcardGeneratorPort."""

from __future__ import annotations

import json
import os
import signal
import subprocess
import time
from datetime import datetime, timedelta, timezone
from typing import TYPE_CHECKING, Any, ClassVar

from rich.console import Console
from rich.progress import (
    BarColumn,
    Progress,
    SpinnerColumn,
    TaskProgressColumn,
    TextColumn,
)

from flashcards_generator.domain.entities import Flashcard
from flashcards_generator.domain.exceptions import (
    ArtifactDownloadError,
    GenerationError,
    NotebookLMResponseError,
    SourceProcessingError,
)
from flashcards_generator.domain.ports.flashcard_generator import (
    FlashcardGeneratorPort,
    GenerationConfig,
)
from flashcards_generator.infrastructure.document_limits import (
    MAX_FLASHCARDS as DEFAULT_MAX_FLASHCARDS,
)
from flashcards_generator.infrastructure.document_limits import (
    MAX_JSON_BYTES as DEFAULT_MAX_JSON_BYTES,
)
from flashcards_generator.infrastructure.logging_config import get_logger

if TYPE_CHECKING:
    from pathlib import Path


logger = get_logger("notebooklm_adapter")

DEFAULT_COMMAND_TIMEOUT = 900
DEFAULT_SOURCE_TIMEOUT = 600
DEFAULT_ARTIFACT_TIMEOUT = 900
PROCESS_CLEANUP_TIMEOUT = 5
RATE_LIMIT_RETRY_DELAY_SECONDS = 300
DOWNLOAD_RETRY_DELAY_SECONDS = 30
MAX_DOWNLOAD_RETRIES = 3


class NotebookLMAdapter(FlashcardGeneratorPort):
    """Adapter for the NotebookLM CLI using a list-argv process contract."""

    MAX_JSON_BYTES = DEFAULT_MAX_JSON_BYTES
    MAX_FLASHCARDS = DEFAULT_MAX_FLASHCARDS

    TRANSIENT_ERROR_PATTERNS: ClassVar[tuple[str, ...]] = (
        "rate limit",
        "too many requests",
        "temporarily unavailable",
        "rpc create_artifact failed",
    )

    def __init__(
        self, notebooklm_path: str, timeout: int = DEFAULT_COMMAND_TIMEOUT
    ):
        self.notebooklm_path = notebooklm_path
        self.timeout = timeout

    def _run_command(
        self,
        args: list[str],
        check: bool = True,
        timeout: int | None = None,
    ) -> tuple[int, str, str]:
        """Run one CLI command and reap it on timeout or cancellation."""
        command_timeout = self.timeout if timeout is None else timeout
        process = subprocess.Popen(
            [self.notebooklm_path, *args],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            encoding="utf-8",
            shell=False,
            start_new_session=True,
        )
        try:
            stdout, stderr = process.communicate(timeout=command_timeout)
        except (KeyboardInterrupt, subprocess.TimeoutExpired):
            self._stop_process(process)
            raise

        if check and process.returncode != 0:
            raise RuntimeError(
                self._command_failure(process.returncode, stderr)
            )
        return process.returncode, stdout, stderr

    def _stop_process(self, process: subprocess.Popen[str]) -> None:
        """Stop the command group where possible and always reap its leader."""
        self._signal_process(process, signal.SIGTERM)
        try:
            process.wait(timeout=PROCESS_CLEANUP_TIMEOUT)
        except subprocess.TimeoutExpired:
            self._signal_process(process, signal.SIGKILL)
            process.wait()

    def _signal_process(
        self, process: subprocess.Popen[str], signal_number: int
    ) -> None:
        """Signal the isolated process group, falling back to its leader."""
        pid = getattr(process, "pid", None)
        if os.name == "posix" and isinstance(pid, int):
            try:
                os.killpg(pid, signal_number)
                return
            except (OSError, ProcessLookupError):
                pass
        if signal_number == signal.SIGTERM:
            process.terminate()
        else:
            process.kill()

    @staticmethod
    def _command_failure(returncode: int, stderr: str) -> str:
        return (
            "NotebookLM command failed "
            f"(status={returncode}, stderr_chars={len(stderr)})"
        )

    @staticmethod
    def _response_error(
        operation: str, reason: str
    ) -> NotebookLMResponseError:
        return NotebookLMResponseError(operation, reason)

    def create_notebook(self, title: str) -> str:
        """Create a new notebook."""
        try:
            _, stdout, _ = self._run_command(["create", title, "--json"])
            data = self._parse_json(stdout, "create notebook")
            notebook_id = self._extract_identifier(
                data, "create notebook", "id", "notebook"
            )
            return notebook_id
        except (RuntimeError, OSError, subprocess.TimeoutExpired) as error:
            raise GenerationError("", str(error)) from error

    def add_source(self, notebook_id: str, pdf_path: Path) -> str:
        """Add a PDF source to notebook."""
        command = [
            "source",
            "add",
            str(pdf_path),
            "--notebook",
            notebook_id,
            "--json",
        ]
        try:
            _, stdout, _ = self._run_command(command)
            data = self._parse_json(stdout, "add source")
            return self._extract_identifier(
                data, "add source", "source_id", "source"
            )
        except (RuntimeError, OSError, subprocess.TimeoutExpired) as error:
            raise SourceProcessingError(pdf_path, str(error)) from error

    def wait_for_source(
        self,
        notebook_id: str,
        source_id: str,
        timeout: int = DEFAULT_SOURCE_TIMEOUT,
    ) -> bool:
        """Wait for source processing within the requested deadline."""
        command = [
            "source",
            "wait",
            source_id,
            "-n",
            notebook_id,
            "--timeout",
            str(timeout),
        ]
        returncode, _, _ = self._run_command(
            command, check=False, timeout=timeout
        )
        return returncode == 0

    def _build_generate_command(
        self, notebook_id: str, config: GenerationConfig
    ) -> list[str]:
        """Build the selected generate flashcards CLI dialect."""
        command = [
            "generate",
            "flashcards",
            "--notebook",
            notebook_id,
            "--difficulty",
            config.difficulty,
            "--quantity",
            config.quantity,
            "--json",
        ]
        if config.instructions:
            command.append(config.instructions.replace("\n", " ").strip())
        return command

    def _needs_retry(self, stderr: str) -> bool:
        """Return whether a failed command reported a transient condition."""
        stderr_lower = stderr.lower()
        return any(
            pattern in stderr_lower
            for pattern in self.TRANSIENT_ERROR_PATTERNS
        )

    def _log_command_result(
        self,
        command: list[str],
        returncode: int,
        stdout: str,
        stderr: str,
        attempt: int,
        timeout: int,
    ) -> None:
        """Log metadata without exposing CLI output, prompts, or credentials."""
        logger.debug(
            "NotebookLM command completed: "
            f"operation={command[0]} status={returncode} attempt={attempt} "
            f"timeout={timeout} stdout_chars={len(stdout)} "
            f"stderr_chars={len(stderr)}"
        )

    def _execute_with_retry(
        self, command: list[str], timeout: int
    ) -> tuple[int, str, str]:
        """Retry exactly one classified transient nonzero generation failure."""
        returncode, stdout, stderr = self._run_command(
            command, check=False, timeout=timeout
        )
        self._log_command_result(
            command, returncode, stdout, stderr, attempt=1, timeout=timeout
        )
        if returncode == 0 or not self._needs_retry(stderr):
            return returncode, stdout, stderr

        logger.warning(
            "NotebookLM generation transient failure; retrying once"
        )
        time.sleep(RATE_LIMIT_RETRY_DELAY_SECONDS)
        returncode, stdout, stderr = self._run_command(
            command, check=False, timeout=timeout
        )
        self._log_command_result(
            command, returncode, stdout, stderr, attempt=2, timeout=timeout
        )
        return returncode, stdout, stderr

    def generate_flashcards(
        self, notebook_id: str, config: GenerationConfig
    ) -> str | None:
        """Generate flashcards, returning ``None`` for optional failure."""
        command = self._build_generate_command(notebook_id, config)
        try:
            returncode, stdout, stderr = self._execute_with_retry(
                command, config.timeout_seconds
            )
        except (OSError, subprocess.TimeoutExpired):
            logger.error("NotebookLM generation failed before completion")
            return None

        if returncode != 0:
            logger.error(
                "NotebookLM generation failed: "
                f"status={returncode} stderr_chars={len(stderr)}"
            )
            return None
        if not stdout.strip():
            logger.error("NotebookLM generation returned empty output")
            return None

        try:
            data = self._parse_json(stdout, "generate flashcards")
            return self._extract_identifier(
                data, "generate flashcards", "task_id", "artifact_id", "id"
            )
        except NotebookLMResponseError:
            logger.error("NotebookLM generation returned an invalid response")
            return None

    def wait_for_artifact(
        self,
        notebook_id: str,
        artifact_id: str,
        timeout: int = DEFAULT_ARTIFACT_TIMEOUT,
    ) -> bool:
        """Wait for artifact generation within the requested deadline."""
        command = [
            "artifact",
            "wait",
            artifact_id,
            "-n",
            notebook_id,
            "--timeout",
            str(timeout),
        ]
        returncode, _, _ = self._run_command(
            command, check=False, timeout=timeout
        )
        return returncode == 0

    def download_flashcards(
        self, notebook_id: str, artifact_id: str, output_path: Path
    ) -> bool:
        """Download flashcards, retrying only transient nonzero failures."""
        command = [
            "download",
            "flashcards",
            "-n",
            notebook_id,
            "-a",
            artifact_id,
            "--format",
            "json",
            str(output_path),
        ]
        for attempt in range(MAX_DOWNLOAD_RETRIES):
            try:
                returncode, _, stderr = self._run_command(command, check=False)
            except (OSError, subprocess.SubprocessError) as error:
                raise ArtifactDownloadError(artifact_id, str(error)) from error

            if returncode == 0:
                return True
            if (
                not self._needs_retry(stderr)
                or attempt == MAX_DOWNLOAD_RETRIES - 1
            ):
                raise ArtifactDownloadError(
                    artifact_id, self._command_failure(returncode, stderr)
                )
            logger.warning(
                "NotebookLM download transient failure: "
                f"attempt={attempt + 1} status={returncode}; retrying"
            )
            time.sleep(DOWNLOAD_RETRY_DELAY_SECONDS * (attempt + 1))

        raise AssertionError(
            "unreachable download retry state"
        )  # pragma: no cover

    def _parse_json(self, stdout: str, operation: str) -> Any:
        if len(stdout.encode("utf-8")) > self.MAX_JSON_BYTES:
            raise self._response_error(
                operation,
                f"JSON exceeds maximum size of {self.MAX_JSON_BYTES} bytes",
            )
        try:
            return json.loads(stdout)
        except json.JSONDecodeError as error:
            raise self._response_error(operation, "invalid JSON") from error

    def _extract_identifier(
        self, data: Any, operation: str, *keys: str
    ) -> str:
        if not isinstance(data, dict):
            raise self._response_error(
                operation, "expected an object response"
            )
        for key in keys:
            identifier = self._identifier_value(data.get(key))
            if identifier is not None:
                return identifier
        raise self._response_error(operation, "missing nonempty identifier")

    @staticmethod
    def _identifier_value(value: Any) -> str | None:
        if isinstance(value, str):
            return value if value.strip() else None
        if isinstance(value, dict):
            nested_id = value.get("id")
            return (
                nested_id
                if isinstance(nested_id, str) and nested_id.strip()
                else None
            )
        return None

    def _extract_cards_data(self, data: Any) -> list[Any]:
        """Extract a schema-valid card array from a response envelope."""
        if isinstance(data, list):
            self._validate_card_count(data)
            return data
        if not isinstance(data, dict):
            raise self._response_error(
                "parse flashcards", "expected an array or object"
            )
        for key in ("cards", "flashcards"):
            if key in data:
                cards = data[key]
                if isinstance(cards, list):
                    self._validate_card_count(cards)
                    return cards
                raise self._response_error(
                    "parse flashcards", f"{key} must be an array"
                )
        raise self._response_error("parse flashcards", "missing cards array")

    def _validate_card_count(self, cards: list[Any]) -> None:
        if len(cards) > self.MAX_FLASHCARDS:
            raise self._response_error(
                "parse flashcards",
                f"card count exceeds maximum of {self.MAX_FLASHCARDS}",
            )

    def _create_flashcard(self, item: dict[str, Any]) -> Flashcard | None:
        """Build a card when both fields are nonempty strings."""
        front = item.get("front", item.get("question", item.get("q", "")))
        back = item.get("back", item.get("answer", item.get("a", "")))
        if (
            isinstance(front, str)
            and front.strip()
            and isinstance(back, str)
            and back.strip()
        ):
            return Flashcard(front=front, back=back)
        return None

    def parse_flashcards(self, json_path: Path) -> list[Flashcard]:
        """Parse a downloaded card response or raise a contextual response error."""
        try:
            if json_path.stat().st_size > self.MAX_JSON_BYTES:
                raise self._response_error(
                    "parse flashcards",
                    f"JSON exceeds maximum size of {self.MAX_JSON_BYTES} bytes",
                )
            data = self._parse_json(
                json_path.read_text(encoding="utf-8"), "parse flashcards"
            )
        except OSError as error:
            raise self._response_error(
                "parse flashcards", "unable to read file"
            ) from error

        flashcards = []
        for index, item in enumerate(self._extract_cards_data(data)):
            if not isinstance(item, dict):
                raise self._response_error(
                    "parse flashcards", f"card {index} must be an object"
                )
            card = self._create_flashcard(item)
            if card is None:
                raise self._response_error(
                    "parse flashcards",
                    f"card {index} has empty or non-string fields",
                )
            flashcards.append(card)
        return flashcards

    def delete_notebook(self, notebook_id: str, silent: bool = False) -> bool:
        """Delete a notebook using the selected CLI dialect."""
        try:
            returncode, _, stderr = self._run_command(
                ["delete", "-n", notebook_id, "-y"], check=False
            )
        except (OSError, subprocess.SubprocessError):
            logger.warning("NotebookLM delete failed before completion")
            return False
        if returncode == 0:
            if not silent:
                logger.info("NotebookLM notebook deleted")
            return True
        logger.warning(
            "NotebookLM delete failed: "
            f"status={returncode} stderr_chars={len(stderr)}"
        )
        return False

    def list_notebooks(self, days: int | None = None) -> list[dict[str, Any]]:
        """List notebooks, optionally filtering by creation date."""
        notebooks = self._load_notebooks()
        if days is None:
            return notebooks
        cutoff = datetime.now(timezone.utc) - timedelta(days=days)
        return [
            notebook
            for notebook in notebooks
            if self._created_on_or_after(notebook, cutoff)
        ]

    def _load_notebooks(self) -> list[dict[str, Any]]:
        data = self._list_notebook_data()
        notebooks = (
            data.get("notebooks", []) if isinstance(data, dict) else data
        )
        if not isinstance(notebooks, list):
            return []
        return [item for item in notebooks if isinstance(item, dict)]

    def _list_notebook_data(self) -> Any:
        try:
            returncode, stdout, stderr = self._run_command(
                ["list", "--json"], check=False
            )
            if returncode != 0:
                logger.error(
                    "NotebookLM list failed: "
                    f"status={returncode} stderr_chars={len(stderr)}"
                )
                return None
            return self._parse_json(stdout, "list notebooks")
        except (NotebookLMResponseError, OSError, subprocess.SubprocessError):
            logger.error("NotebookLM list returned an invalid response")
            return None

    def _created_on_or_after(
        self, notebook: dict[str, Any], cutoff: datetime
    ) -> bool:
        created = self._parse_datetime(
            notebook.get("created_at") or notebook.get("created")
        )
        return created is None or created >= cutoff

    def _parse_datetime(self, dt_str: Any) -> datetime | None:
        if not isinstance(dt_str, str):
            return None
        formats = [
            "%Y-%m-%dT%H:%M:%S.%fZ",
            "%Y-%m-%dT%H:%M:%SZ",
            "%Y-%m-%dT%H:%M:%S",
            "%Y-%m-%d %H:%M:%S",
            "%Y-%m-%d",
        ]
        for fmt in formats:
            try:
                return datetime.strptime(dt_str, fmt).replace(
                    tzinfo=timezone.utc
                )
            except ValueError:
                continue
        return None

    def delete_all_notebooks(
        self, days: int | None = None, show_progress: bool = False
    ) -> tuple[int, int]:
        """Delete all notebooks. Returns ``(deleted_count, failed_count)``."""
        notebooks = self.list_notebooks(days=days)
        if not notebooks:
            logger.info("No notebooks found to delete")
            return 0, 0

        if show_progress:
            deleted, failed = self._delete_with_progress(notebooks)
        else:
            deleted, failed = self._delete_without_progress(notebooks)

        logger.info(f"Cleanup complete: {deleted} deleted, {failed} failed")
        return deleted, failed

    def _delete_with_progress(
        self, notebooks: list[dict[str, Any]]
    ) -> tuple[int, int]:
        with Progress(
            SpinnerColumn(),
            TextColumn("[bold blue]{task.description}"),
            BarColumn(bar_width=40),
            TaskProgressColumn(),
            console=Console(),
        ) as progress:
            task = progress.add_task(
                f"Deleting {len(notebooks)} notebooks...",
                total=len(notebooks),
            )
            outcomes = []
            for notebook in notebooks:
                notebook_id = self._notebook_id(notebook)
                if notebook_id:
                    outcomes.append(
                        self.delete_notebook(notebook_id, silent=True)
                    )
                progress.update(task, advance=1)
        return outcomes.count(True), outcomes.count(False)

    def _delete_without_progress(
        self, notebooks: list[dict[str, Any]]
    ) -> tuple[int, int]:
        logger.info(f"Found {len(notebooks)} notebook(s) to delete...")
        outcomes = []
        for index, notebook in enumerate(notebooks, 1):
            notebook_id = self._notebook_id(notebook)
            if notebook_id:
                logger.info(f"[{index}/{len(notebooks)}] Deleting notebook...")
                outcomes.append(self.delete_notebook(notebook_id))
        return outcomes.count(True), outcomes.count(False)

    @staticmethod
    def _notebook_id(notebook: Any) -> str | None:
        value = notebook.get("id") if isinstance(notebook, dict) else notebook
        return value if isinstance(value, str) and value else None

"""Port for flashcard generation services."""

from __future__ import annotations

from abc import ABC, abstractmethod
from typing import TYPE_CHECKING

from pydantic import BaseModel, Field

from flashcards_generator.domain.entities import Deck

if TYPE_CHECKING:
    from pathlib import Path

    from flashcards_generator.domain.entities import Flashcard


class GenerationConfig(BaseModel):
    """Configuration for flashcard generation."""

    difficulty: str = Field(default="medium")
    quantity: str = Field(default="standard")
    instructions: str = Field(default="")
    timeout_seconds: int = Field(default=900)
    wait_for_completion: bool = Field(default=True)


class GenerationResult(BaseModel):
    """Result of flashcard generation."""

    deck: Deck
    artifact_id: str | None = Field(default=None)
    completed: bool = Field(default=False)


class FlashcardGeneratorPort(ABC):
    """Port for generating flashcards from PDF sources.

    Implementations:
        - NotebookLMAdapter: Uses Google NotebookLM API
        - MockGenerator: For testing
    """

    @abstractmethod
    def create_notebook(self, title: str) -> str:
        """Create a new notebook and return its ID."""
        # pragma: no cover

    @abstractmethod
    def add_source(self, notebook_id: str, pdf_path: Path) -> str:
        """Add a PDF source to a notebook. Returns source ID."""
        # pragma: no cover

    @abstractmethod
    def wait_for_source(
        self, notebook_id: str, source_id: str, timeout: int = 600
    ) -> bool:
        """Wait for source processing to complete."""
        # pragma: no cover

    @abstractmethod
    def generate_flashcards(
        self,
        notebook_id: str,
        config: GenerationConfig,
    ) -> str | None:
        """Generate flashcards. Returns artifact ID or None."""
        # pragma: no cover

    @abstractmethod
    def wait_for_artifact(
        self, notebook_id: str, artifact_id: str, timeout: int = 900
    ) -> bool:
        """Wait for artifact generation to complete."""
        # pragma: no cover

    @abstractmethod
    def download_flashcards(
        self, notebook_id: str, artifact_id: str, output_path: Path
    ) -> bool:
        """Download generated flashcards to file."""
        # pragma: no cover

    @abstractmethod
    def parse_flashcards(self, json_path: Path) -> list[Flashcard]:
        """Parse flashcards from downloaded JSON."""
        # pragma: no cover

    @abstractmethod
    def delete_notebook(self, notebook_id: str) -> bool:
        """Delete a notebook. Returns success status."""
        # pragma: no cover

"""DTO for CSV merge use case."""

from pathlib import Path, PurePath

from pydantic import BaseModel, Field, field_validator


class MergeCsvRequest(BaseModel):
    """Request to merge CSV flashcard files."""

    model_config = {"arbitrary_types_allowed": True}

    folder_path: Path
    output_filename: str = Field(default="merged_flashcards.csv")
    deduplicate: bool = Field(default=False)

    @field_validator("output_filename")
    @classmethod
    def validate_output_filename(cls, value: str) -> str:
        path = PurePath(value)
        if not value or path.is_absolute() or path.name != value:
            raise ValueError(
                "output_filename must be a nonempty relative basename"
            )
        return value

    recursive: bool = Field(default=True)

"""Filesystem-backed repository for chunk resume state."""

from __future__ import annotations

import fcntl
import os
import secrets
import shutil
import stat
from collections.abc import Generator, Iterator
from contextlib import contextmanager
from pathlib import Path

from flashcards_generator.domain.entities import ChunkResumeManifest, Deck
from flashcards_generator.domain.ports import ChunkStatePort
from flashcards_generator.infrastructure.logging_config import get_logger

logger = get_logger("chunk_state_repository")

_DIRECTORY_MODE = 0o700
_FILE_MODE = 0o600


class FileSystemChunkStateRepository(ChunkStatePort):
    """Persist private chunk manifests and result decks as JSON files."""

    def load_manifest(self, state_path: Path) -> ChunkResumeManifest | None:
        """Load a chunk resume manifest from disk if present."""
        try:
            content = self._read_text(state_path)
        except FileNotFoundError:
            logger.debug(f"Manifest not found: {state_path}")
            return None

        logger.debug(f"Loading manifest from {state_path}")
        return ChunkResumeManifest.model_validate_json(content)

    def save_manifest(
        self, state_path: Path, manifest: ChunkResumeManifest
    ) -> None:
        """Persist a chunk resume manifest with a durable atomic replacement."""
        logger.debug(f"Saving manifest to {state_path}")
        self._atomic_write(state_path, manifest.model_dump_json(indent=2))

    def delete_manifest(self, state_path: Path) -> None:
        """Delete a persisted manifest without following a symlink."""
        try:
            state_path.unlink()
        except FileNotFoundError:
            return
        logger.debug(f"Deleting manifest at {state_path}")

    def save_chunk_result(self, path: Path, deck: Deck) -> None:
        """Persist an individual chunk result deck atomically."""
        logger.debug(f"Saving chunk result to {path}")
        self._atomic_write(path, deck.model_dump_json(indent=2))

    def load_chunk_result(self, path: Path) -> Deck:
        """Load an individual chunk result deck without following symlinks."""
        logger.debug(f"Loading chunk result from {path}")
        return Deck.model_validate_json(self._read_text(path))

    def delete_chunk_results(self, dir_path: Path) -> None:
        """Delete only the requested result directory."""
        try:
            mode = dir_path.lstat().st_mode
        except FileNotFoundError:
            return

        if stat.S_ISLNK(mode):
            dir_path.unlink()
        else:
            logger.debug(f"Deleting chunk results directory {dir_path}")
            shutil.rmtree(dir_path)

    @contextmanager
    def resume_lock(self, resume_dir: Path) -> Generator[bool, None, None]:
        """Acquire non-blocking exclusive ownership of a resume directory."""
        self._ensure_private_directory(resume_dir.parent)
        directory_fd = self._open_directory(resume_dir.parent)
        lock_fd: int | None = None
        try:
            lock_fd = os.open(
                f".{resume_dir.name}.lock",
                os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW,
                _FILE_MODE,
                dir_fd=directory_fd,
            )
            os.fchmod(lock_fd, _FILE_MODE)
            try:
                fcntl.flock(lock_fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
            except BlockingIOError:
                yield False
                return

            yield True
        finally:
            if lock_fd is not None:
                with suppress_os_error():
                    fcntl.flock(lock_fd, fcntl.LOCK_UN)
                os.close(lock_fd)
            os.close(directory_fd)

    def _read_text(self, path: Path) -> str:
        self._assert_no_symlink_parents(path.parent)
        flags = os.O_RDONLY | os.O_NOFOLLOW
        fd = os.open(path, flags)
        try:
            if not stat.S_ISREG(os.fstat(fd).st_mode):
                raise OSError(f"State path is not a regular file: {path}")
            with os.fdopen(fd, encoding="utf-8") as file_obj:
                fd = -1
                return file_obj.read()
        finally:
            if fd != -1:
                os.close(fd)

    def _atomic_write(self, path: Path, content: str) -> None:
        """Write content with a unique, private sibling temporary file."""
        self._ensure_private_directory(path.parent)
        directory_fd = self._open_directory(path.parent)
        temp_name = f".{path.name}.{secrets.token_hex(16)}.tmp"
        temp_fd: int | None = None
        try:
            temp_fd = os.open(
                temp_name,
                os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW,
                _FILE_MODE,
                dir_fd=directory_fd,
            )
            os.fchmod(temp_fd, _FILE_MODE)
            with os.fdopen(temp_fd, "w", encoding="utf-8") as file_obj:
                temp_fd = None
                file_obj.write(content)
                file_obj.flush()
                os.fsync(file_obj.fileno())
            os.replace(
                temp_name,
                path.name,
                src_dir_fd=directory_fd,
                dst_dir_fd=directory_fd,
            )
            os.fsync(directory_fd)
        except Exception:
            if temp_fd is not None:
                os.close(temp_fd)
            with suppress_os_error():
                os.unlink(temp_name, dir_fd=directory_fd)
            raise
        finally:
            os.close(directory_fd)

    def _ensure_private_directory(self, directory: Path) -> None:
        current = Path(directory.anchor)
        parts = (
            directory.parts[1:] if directory.is_absolute() else directory.parts
        )
        for part in parts:
            current /= part
            try:
                mode = current.lstat().st_mode
            except FileNotFoundError:
                current.mkdir(mode=_DIRECTORY_MODE)
                mode = current.lstat().st_mode
            if stat.S_ISLNK(mode) or not stat.S_ISDIR(mode):
                raise OSError(
                    f"State directory is not a real directory: {current}"
                )
        os.chmod(directory, _DIRECTORY_MODE)

    def _assert_no_symlink_parents(self, directory: Path) -> None:
        current = Path(directory.anchor)
        parts = (
            directory.parts[1:] if directory.is_absolute() else directory.parts
        )
        for part in parts:
            current /= part
            mode = current.lstat().st_mode
            if stat.S_ISLNK(mode) or not stat.S_ISDIR(mode):
                raise OSError(
                    f"State directory is not a real directory: {current}"
                )

    @staticmethod
    def _open_directory(directory: Path) -> int:
        return os.open(directory, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)


@contextmanager
def suppress_os_error() -> Iterator[None]:
    try:
        yield
    except OSError:
        pass

